import{z as B,x as d,o as E,c as A,q as r,j as s,D as n,d as o,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"浮点异常与标志","description":"","frontmatter":{"title":"浮点异常与标志","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fp-exceptions.md","filePath":"cs/fp-exceptions.md","lastUpdated":1791063341000}'),p={name:"cs/fp-exceptions.md"};function f(c,a,D,m,u,C){const t=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=r('<h1 id="浮点异常与标志" tabindex="-1">浮点异常与标志 <a class="header-anchor" href="#浮点异常与标志" aria-label="Permalink to &quot;浮点异常与标志&quot;">​</a></h1><div class="epigraph"><p>754 把五种异常钉成状态位：无效、除零、上溢、下溢、不精确；默认常常不陷阱，只记下，让软件事后读。</p><footer>—— 据 IEEE Std 754-2008；Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume I 整理</footer></div><p><a href="/cs/fp-mul-fma">上一课</a>的乘与 FMA 会在指数两端和不精确格子上「出事」，加法器同样。<a href="/cs/ieee-754">IEEE 754</a> 把 NaN 与无穷写成位型，还没有说硬件何时置位、软件何时看见。缺口是：<strong>异常检测点与标志寄存器</strong>，不是再解释什么是 NaN。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五种标准异常：invalid（无序运算、\\(\\sqrt{-}\\)、0/0 等）、division by zero（有限/0 得无穷）、overflow、underflow、inexact。默认响应是递送结果（无穷、NaN、最大有限数或非规格化）并置 sticky 标志。缺口不是新的算术，而是：ALU 各路径上的比较器与指数饱和逻辑要接到一组 <strong>accrued flags</strong>，通常不自动陷入。</p><p><span class="marginnote">术语翻译「粘滞位」：像烟雾报警器上的指示灯——不管烟雾多小、什么时候飘过，灯一亮就一直亮着，直到有人手动复位。软件因此只需要最后读一次标志，就知道「自上次清除以来出过哪些事」，不必每条指令都去查岗。</span></p><p>RISC-V <code>fflags</code> CSR 就是这五位；<code>frm</code> 是<a href="/cs/rounding-modes">舍入模式</a>。本课不把 <code>mtvec</code> 陷阱入口重讲一遍，只承认「若使能陷阱则改走异常入口」。</p><h3 id="标志不是「errno」" tabindex="-1">标志不是「errno」 <a class="header-anchor" href="#标志不是「errno」" aria-label="Permalink to &quot;标志不是「errno」&quot;">​</a></h3><p>它们是粘滞位：一次不精确会一直留到软件清。语言级的 <code>errno</code> 或异常对象是另一层。把每次 <code>fadd</code> 当系统调用错误码，流水线无法把标志接到 CSR 写口。NaN 载荷与 quiet/signaling 决定 invalid 是否在比较时触发——位型课已分无穷与 NaN，本课只接线。</p><p><span class="marginnote">754-2008 §7 规定异常。RISC-V 用户手册把 <code>fflags</code> 列为浮点 CSR。Patterson/Hennessy 教学常省略标志，本补层补上，因为后课定点 DSP 的饱和是另一套「出错」哲学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在规格化与舍入之后采样：指数超过最大值 → overflow（常同时 inexact）；结果非零且指数低于最小值 → underflow（与 tininess 检测时机有关，本课点名不背条款号）；GRS 非零 → inexact；操作数是 sNaN 或无效组合 → invalid；除零规则独立。FMA 只产生一组标志，对应那一次舍入。</p>',12)),(E(),s(l,null,{default:n(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PATH%5B%22%E5%8A%A0%20%2F%20%E4%B9%98%20%2F%20FMA%20%2F%20%E9%99%A4%22%5D%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%E4%BA%94%E7%A7%8D%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20DET%20--%3E%20FLG%5B%22%E7%B2%98%E6%BB%9E%20fflags%22%5D%0A%20%20DET%20--%3E%20TRAP%5B%22%E5%8F%AF%E9%80%89%EF%BC%9A%E4%BD%BF%E8%83%BD%E5%88%99%E9%99%B7%E5%85%A5%22%5D%0A%20%20FLG%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ALZC%20%E8%A7%84%E6%A0%BC%E5%8C%96%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"软件：读标志做区间诊断或调试；数值库很少每条指令清一次。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者以为浮点上溢会像整数溢出那样抛异常、程序崩溃。默认恰恰相反：754 递送 \\(\\pm\\infty\\) 或 NaN 让程序继续跑，只有显式使能陷阱才中断。深度学习里「loss 悄悄变 NaN 还在训练」的静默失败，根源正是这套默认不陷阱的哲学。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"下两课前导零计数是规格化硬件，也影响 underflow（左规后是否仍低于最小指数）。定点溢出检测是整数旗标，不要与这五位混进同一个 CSR。后课 HDL 实现时，这些位是流水线写回的副作用，须与结果同拍提交，否则乱序 FPU 会把后来指令的标志提前粘上——微结构问题，本课只钉语义。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"为什么「标志与结果同拍提交」重要：乱序执行的 FPU 若把某条指令的 inexact 提前粘到寄存器上，调试者读标志时会把异常算到还没执行的指令头上，诊断方向整个带偏。副作用和结果必须原子落地，否则「事后读一次」的诊断模型就失信了。")],-1)),(E(),s(l,null,{default:n(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22%E8%BD%AF%E4%BB%B6%E6%B8%85%E9%9B%B6%20fflags%22%5D%20--%3E%20OP1%5B%22%E6%8C%87%E4%BB%A41%3A%E7%BB%93%E6%9E%9C%E4%B8%8D%E7%B2%BE%E7%A1%AE%22%5D%0A%20%20OP1%20--%3E%20SET%5B%22inexact%20%E4%BD%8D%3D1%22%5D%0A%20%20SET%20--%3E%20OP2%5B%22%E6%8C%87%E4%BB%A42%3A%E7%B2%BE%E7%A1%AE%2C%E6%97%A0%E5%BC%82%E5%B8%B8%22%5D%0A%20%20OP2%20--%3E%20KEEP%5B%22%E6%A0%87%E5%BF%97%E4%BF%9D%E6%8C%81%201%3A%E7%B2%98%E6%BB%9E%2C%E4%B8%8D%E6%B8%85%E9%9B%B6%22%5D%0A%20%20KEEP%20--%3E%20OP3%5B%22%E6%8C%87%E4%BB%A43%3A%E4%B8%8A%E6%BA%A2%22%5D%0A%20%20OP3%20--%3E%20BOTH%5B%22overflow%20%E7%BD%AE%201%2Cinexact%20%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20BOTH%20--%3E%20RD%5B%22%E8%BD%AF%E4%BB%B6%E8%AF%BB%E4%B8%80%E6%AC%A1%3A%E7%9C%8B%E5%88%B0%E5%85%A8%E8%BF%87%E7%A8%8B%E7%9A%84%E7%B4%AF%E8%AE%A1%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 754 的 alternate exception handling 全部条款，不把 Unix SIGFPE 默认打开。不讨论十进制格式的额外异常。也不把「模型训练里忽略 NaN」写成规范。</p><p>后课默认：浮点运算更新五位粘滞标志；默认不陷阱；与整数溢出旗标分家。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五种 754 异常接到粘滞标志，默认递送结果。</li><li>RISC-V 上是 <code>fflags</code>；陷阱是可选使能。</li><li>FMA 对应一次舍入、一组标志。</li><li>出处：IEEE 754-2008；RISC-V ISA Manual, Vol. I；Patterson and Hennessy, COD (RISC-V)。</li></ul>',5))])}const S=B(p,[["render",f]]);export{P as __pageData,S as default};
